/* ================= fixed-timestep loop ================= */
const STEP=1000/60;
let acc=0,last=0;
function loop(ts){
  if(!last)last=ts;
  let dt=ts-last;
  last=ts;
  if(dt>100)dt=100;
  acc+=dt;
  while(acc>=STEP){
    update();
    acc-=STEP;
  }
  render();
  requestAnimationFrame(loop);
}
